<script setup>
import { ref, computed, watch, onMounted, onUnmounted } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { api, query } from '../api'
import { auth, clearAuth, categories, statuses, date } from '../state'
import Icon from '../components/Icon.vue'
import CampusModuleNav from '../components/CampusModuleNav.vue'
const router = useRouter(), route = useRoute()
const tab = computed(() => ['monitor', 'feedback'].includes(route.params.tab) ? route.params.tab : 'documents')
const title = computed(() => ({ documents: '规章文档', monitor: '运行概览', feedback: '学生反馈' }[tab.value]))
const docs = ref([]), total = ref(0), page = ref(1), size = 10, summary = ref(null), quality = ref(null), feedback = ref([]), feedbackTotal = ref(0), feedbackPage = ref(1)
const error = ref(''), notice = ref(''), loading = ref(false), actionBusy = ref(false), showSide = ref(false)
const filter = ref({ keyword: '', category: '', vectorStatus: '', lifecycleStatus: '' }), rating = ref(''), from = ref(''), to = ref('')
const uploadOpen = ref(false), uploadTitle = ref(''), uploadCategory = ref('STUDENT_STATUS'), uploadFile = ref(null), fileInput = ref(null)
const detail = ref(null), editing = ref(false), editTitle = ref(''), editCategory = ref(''), feedbackDetail = ref(null)
const pageVisible = ref(document.visibilityState === 'visible')
const refreshFailed = ref(false)
const hasRunningTasks = computed(() => {
  const distribution = summary.value?.statusDistribution
  return (distribution?.PENDING || 0) > 0 || (distribution?.PROCESSING || 0) > 0
    || (summary.value?.pendingDeletionCount ?? summary.value?.deletingCount ?? 0) > 0
    || (tab.value === 'monitor' && (quality.value?.processingCount || 0) > 0)
})
const canAutoRefresh = computed(() => hasRunningTasks.value && tab.value !== 'feedback'
  && pageVisible.value && !uploadOpen.value && !(editing.value && detail.value)
  && !actionBusy.value && !loading.value && !error.value && !refreshFailed.value)
const tabs = [{ key: 'documents', label: '规章文档', icon: 'file' }, { key: 'monitor', label: '运行概览', icon: 'chart' }, { key: 'feedback', label: '学生反馈', icon: 'feedback' }]
function logout() { clearAuth(); router.push('/login') }
function dates() { return { from: from.value ? new Date(from.value).toISOString() : '', to: to.value ? new Date(to.value).toISOString() : '' } }
async function loadDocuments() { const data = await api(`/admin/documents?${query({ ...filter.value, page: page.value, size })}`); docs.value = data.records; total.value = data.total }
async function loadFeedback() { const data = await api(`/admin/feedback?${query({ rating: rating.value, ...dates(), page: feedbackPage.value, size })}`); feedback.value = data.records; feedbackTotal.value = data.total }
async function refresh() {
  if (loading.value) return
  loading.value = true; error.value = ''; refreshFailed.value = false
  try {
    summary.value = await api('/admin/monitor/summary')
    if (tab.value === 'documents') await loadDocuments()
    if (tab.value === 'monitor') quality.value = await api(`/admin/monitor/qa?${query(dates())}`)
    if (tab.value === 'feedback') await loadFeedback()
    if (detail.value) detail.value = await api(`/admin/documents/${detail.value.docId}`)
  } catch (e) { error.value = e.message; refreshFailed.value = true } finally { loading.value = false }
}
async function search() { page.value = 1; feedbackPage.value = 1; await refresh() }
function pickFile(e) { uploadFile.value = e.target.files[0] || null; if (uploadFile.value && !uploadTitle.value) uploadTitle.value = uploadFile.value.name.replace(/\.[^.]+$/, '') }
async function upload() {
  if (!uploadFile.value) { error.value = '请选择文件'; return }
  if (uploadFile.value.size > 20 * 1024 * 1024) { error.value = '文件不得超过 20 MiB'; return }
  if ([...uploadTitle.value.trim()].length < 1 || [...uploadTitle.value.trim()].length > 100) { error.value = '标题须为 1～100 个字符'; return }
  actionBusy.value = true; error.value = ''
  try {
    const form = new FormData(); form.append('file', uploadFile.value); form.append('title', uploadTitle.value); form.append('category', uploadCategory.value)
    await api('/admin/documents', { method: 'POST', body: form }); uploadOpen.value = false; uploadFile.value = null; uploadTitle.value = ''; notice.value = '文档已受理，后台正在解析和建立索引。'; page.value = 1; await refresh()
  } catch (e) {
    const reason = `${e.message}。若未收到受理结果，请先刷新列表确认。`
    try { await refresh() } finally { error.value = reason }
  } finally { actionBusy.value = false }
}
async function inspect(d) { try { detail.value = await api(`/admin/documents/${d.docId}`); editing.value = false } catch (e) { error.value = e.message } }
function edit(d) { detail.value = d; editing.value = true; editTitle.value = d.title; editCategory.value = d.category }
async function saveEdit() {
  actionBusy.value = true
  try { await api(`/admin/documents/${detail.value.docId}`, { method: 'PATCH', body: { title: editTitle.value, category: editCategory.value } }); editing.value = false; notice.value = '文档展示信息已更新'; await refresh() } catch (e) { error.value = e.message } finally { actionBusy.value = false }
}
async function rebuild(d) {
  if (!confirm(`确认全量重建「${d.title}」的索引？已有知识会保留至新代次成功。`)) return
  actionBusy.value = true
  try { await api(`/admin/documents/${d.docId}/revectorize`, { method: 'POST' }); notice.value = '重建任务已受理'; await refresh() } catch (e) { error.value = e.message } finally { actionBusy.value = false }
}
async function remove(d) {
  if (!confirm(`确认删除「${d.title}」？将立即停止新检索使用，历史回答引用仍保留。`)) return
  actionBusy.value = true
  try { await api(`/admin/documents/${d.docId}`, { method: 'DELETE' }); notice.value = '已停用文档并受理清理任务'; await refresh() } catch (e) { error.value = e.message } finally { actionBusy.value = false }
}
function pct(v) { return ((v || 0) * 100).toFixed(1) + '%' }
let poll
function scheduleRefresh() {
  clearTimeout(poll)
  if (canAutoRefresh.value) poll = setTimeout(refresh, 4000)
}
function updateVisibility() { pageVisible.value = document.visibilityState === 'visible' }
watch(canAutoRefresh, scheduleRefresh)
onMounted(() => { document.addEventListener('visibilitychange', updateVisibility); refresh() })
onUnmounted(() => { clearTimeout(poll); document.removeEventListener('visibilitychange', updateVisibility) })
watch(tab, () => { detail.value = null; error.value = ''; notice.value = ''; showSide.value = false; refresh() })
</script>
<template>
  <div class="workspace admin-workspace">
    <button v-if="showSide" class="mobile-scrim" aria-label="关闭导航" @click="showSide = false"></button>
    <aside class="sidebar admin-module-sidebar" :class="{ 'side-open': showSide }"><div class="brand"><span class="brand-mark"><Icon name="book" :size="23" /></span><div>校规知问<small>ADMIN WORKSPACE</small></div></div><div class="admin-sidebar-body"><div class="side-label admin-side-label">知识库工作台</div><nav class="admin-nav admin-primary-nav"><router-link v-for="t in tabs" :key="t.key" :to="t.key === 'documents' ? '/admin' : `/admin/${t.key}`" :class="{ active: tab === t.key }"><Icon :name="t.icon" :size="19" />{{ t.label }}<span v-if="t.key === 'documents' && summary" class="nav-count">{{ summary.totalDocuments }}</span></router-link></nav><CampusModuleNav admin @navigate="showSide = false" /><div class="side-tip"><Icon name="shield" :size="20" /><strong>维护知识，也维护可信</strong><p>请仅上传当前适用的校园规章。<br>更新正文时上传新文件，<br>再停用旧文档。</p></div></div><div class="user-card"><div class="avatar admin-avatar">管</div><div><strong>{{ auth.user?.realName }}</strong><small>系统管理员</small></div><button class="icon-button" aria-label="退出登录" @click="logout"><Icon name="logout" :size="18" /></button></div></aside>
    <main class="main-panel"><header class="topbar"><div class="header-title"><button class="icon-button mobile-menu" aria-label="打开导航" @click="showSide = !showSide"><Icon name="menu" /></button><span class="muted">知识库工作台</span><Icon name="chevron" :size="14" /><span>{{ title }}</span></div><div class="header-actions"><span class="status-dot"></span><span class="small muted">管理中心</span></div></header>
      <div class="admin-content"><div class="page-heading"><div><div class="eyebrow">{{ tab === 'documents' ? 'KNOWLEDGE LIBRARY' : tab === 'monitor' ? 'SYSTEM INSIGHTS' : 'STUDENT VOICES' }}</div><h1>{{ title }}</h1><p class="muted">{{ tab === 'documents' ? '统一管理校园规章，为每一次问答提供可靠依据。' : tab === 'monitor' ? '了解知识库状态与问答表现，及时发现覆盖缺口。' : '倾听学生的使用体验，持续完善知识内容。' }}</p></div><button v-if="tab === 'documents'" class="primary" @click="uploadOpen = true; error = ''"><Icon name="plus" :size="18" />上传规章文档</button><button v-else class="secondary" :disabled="loading" @click="refresh"><Icon name="refresh" :size="17" />刷新数据</button></div>
      <div v-if="error" class="error" role="alert">{{ error }}<button class="icon-button" aria-label="关闭错误" @click="error = ''"><Icon name="close" :size="16" /></button></div><div v-if="notice" class="success-notice" role="status"><Icon name="check" :size="16" />{{ notice }}<button class="icon-button" aria-label="关闭通知" @click="notice = ''"><Icon name="close" :size="16" /></button></div>
      <div v-if="summary" class="stat-grid"><div class="stat-card"><div><span>有效规章文档</span><Icon name="file" :size="18" /></div><strong>{{ summary.totalDocuments }}<small>份</small></strong><p>当前处于启用状态的文档</p></div><div class="stat-card"><div><span>可检索文档</span><Icon name="search" :size="18" /></div><strong>{{ summary.searchableDocumentCount }}<small>份</small></strong><p>已激活有效索引的知识</p></div><div class="stat-card"><div><span>有效知识分块</span><Icon name="book" :size="18" /></div><strong>{{ summary.totalChunks.toLocaleString() }}<small>块</small></strong><p>仅统计当前生效的索引代次</p></div><div class="stat-card"><div><span>最近任务完成率</span><Icon name="chart" :size="18" /></div><strong>{{ pct(summary.completionRate) }}</strong><p>{{ summary.completedCount }} / {{ summary.totalDocuments }} 份有效文档处理完成</p></div></div>
      <section v-if="tab === 'documents'" class="panel library-panel"><div class="panel-heading"><div><h2>全部规章</h2><span class="count-label">{{ total }} 份文档</span></div><button class="text-button" :disabled="loading" @click="refresh"><Icon name="refresh" :size="15" />刷新</button></div><form class="filter-bar" @submit.prevent="search"><div class="search-input"><Icon name="search" :size="17" /><input v-model="filter.keyword" placeholder="搜索文档标题" aria-label="搜索文档标题" maxlength="100"></div><select v-model="filter.category" aria-label="文档分类" @change="search"><option value="">全部分类</option><option v-for="(label, code) in categories" :value="code" :key="code">{{ label }}</option></select><select v-model="filter.vectorStatus" aria-label="处理状态" @change="search"><option value="">全部处理状态</option><option v-for="s in ['PENDING', 'PROCESSING', 'COMPLETED', 'FAILED']" :key="s" :value="s">{{ statuses[s] }}</option></select><select v-model="filter.lifecycleStatus" aria-label="文档生命周期" @change="search"><option value="">当前文档</option><option value="ACTIVE">启用中</option><option value="DELETING">正在删除</option><option value="DELETED">已删除</option></select><button class="secondary">查询</button></form>
        <div class="table-scroll"><table><thead><tr><th>文档名称</th><th>分类</th><th>处理状态</th><th>知识分块</th><th>上传时间</th><th>操作</th></tr></thead><tbody><tr v-for="d in docs" :key="d.docId"><td><button class="document-title" @click="inspect(d)"><span :class="['file-symbol', d.fileType.toLowerCase()]"><Icon name="file" :size="22" /><small>{{ d.fileType }}</small></span><span><strong>{{ d.title }}</strong><small>{{ d.searchable ? '可用于问答检索' : d.lifecycleStatus === 'ACTIVE' ? '暂不可检索' : statuses[d.lifecycleStatus] }}</small></span></button></td><td><span class="category-tag">{{ categories[d.category] }}</span></td><td><span :class="['badge', d.vectorStatus.toLowerCase()]"><span class="mini-dot"></span>{{ statuses[d.vectorStatus] }}</span><small v-if="d.lastError" class="table-error" :title="d.lastError.message">{{ d.lastError.code }} · {{ d.lastError.message }}</small><small v-if="d.cleanupError" class="table-error">{{ d.cleanupError.message }}</small></td><td>{{ d.chunkCount }} <span class="muted">块</span></td><td class="time-cell">{{ date(d.uploadTime) }}</td><td><div class="table-actions"><button class="text-button" @click="inspect(d)">详情</button><button v-if="d.lifecycleStatus === 'ACTIVE'" class="text-button" :disabled="actionBusy" @click="edit(d)">编辑</button><button v-if="d.lifecycleStatus === 'ACTIVE'" class="text-button" :disabled="actionBusy || ['PENDING', 'PROCESSING'].includes(d.vectorStatus)" @click="rebuild(d)">重建</button><button v-if="d.lifecycleStatus !== 'DELETED'" class="text-button danger" :disabled="actionBusy" @click="remove(d)">{{ d.lifecycleStatus === 'DELETING' ? '重试清理' : '删除' }}</button></div></td></tr><tr v-if="!docs.length"><td colspan="6"><div class="empty-state"><Icon name="book" :size="32" /><h3>还没有符合条件的文档</h3><p>上传一份规章，开始构建校园知识库</p></div></td></tr></tbody></table></div><div class="pagination"><span>共 {{ total }} 条 · 每页 {{ size }} 条</span><div><button class="secondary" :disabled="page <= 1" @click="page--; refresh()">上一页</button><span>{{ page }} / {{ Math.max(1, Math.ceil(total / size)) }}</span><button class="secondary" :disabled="page * size >= total" @click="page++; refresh()">下一页</button></div></div></section>
      <div v-if="tab === 'documents'" class="info-footer"><Icon name="shield" :size="16" /><span>支持 PDF、DOCX、UTF-8 TXT，单文件不超过 20 MiB。扫描件请先转换为可提取文本。</span><span class="auto-refresh">{{ refreshFailed ? "自动更新已暂停，可手动刷新" : hasRunningTasks ? "任务处理中，每 4 秒更新状态" : "暂无后台任务，按需刷新" }}</span></div>
      <template v-if="tab === 'monitor'"><section v-if="summary?.runtime" class="panel"><div class="panel-heading"><h2>问答引擎</h2><span class="muted small">当前运行配置</span></div><dl class="detail-grid" style="padding:0 20px 20px"><dt>回答模型</dt><dd>{{ summary.runtime.chatModel }}</dd><dt>检索方式</dt><dd>{{ summary.runtime.retrievalMode === 'hybrid' ? '关键词与向量混合检索（RRF）' : '向量检索' }}</dd><dt>嵌入模型</dt><dd>{{ summary.runtime.embeddingModel }} · {{ summary.runtime.embeddingDimension }} 维</dd><dt>向量存储</dt><dd>{{ summary.runtime.vectorStore }}</dd></dl><p v-if="summary.runtime.embeddingMode === 'local'" class="panel-note">当前使用本地字符特征检索；真实模型负责整理回答与理解追问。语义检索质量需配置独立嵌入服务后评估。</p></section><section class="panel"><div class="panel-heading"><h2>文档任务状态</h2><span class="muted small">最新任务 · 不等同于可检索状态</span></div><div class="distribution" v-if="summary"><div v-for="(count, state) in summary.statusDistribution" :key="state"><span :class="['badge', state.toLowerCase()]"><span class="mini-dot"></span>{{ statuses[state] }}</span><strong>{{ count }}</strong><div class="bar-track"><span :style="{ width: pct(count / (summary.totalDocuments || 1)) }"></span></div></div></div><p class="panel-note">正在删除：{{ summary?.deletingCount || 0 }} 份。重建失败但保有旧代次的文档，仍可用于检索。</p></section><section class="panel quality-panel"><div class="panel-heading"><h2>问答表现</h2><span class="muted small">默认最近 30 天</span></div><form class="filter-bar" @submit.prevent="search"><label>起始时间<input v-model="from" type="datetime-local" aria-label="起始时间"></label><label>结束时间<input v-model="to" type="datetime-local" aria-label="结束时间"></label><button class="secondary">查询</button></form><template v-if="quality"><div class="quality-stats"><div v-for="(label, key) in { totalQuestions: '逻辑问题总数', answeredCount: '有依据回答', noMatchCount: '未命中', insufficientEvidenceCount: '证据不足', failedCount: '技术失败', processingCount: '处理中' }" :key="key"><strong>{{ quality[key] }}</strong><span>{{ label }}</span></div></div><div class="rate-row"><span>检索命中率 <strong>{{ pct(quality.retrievalHitRate) }}</strong></span><span>回答率 <strong>{{ pct(quality.answerRate) }}</strong></span><span>技术失败率 <strong>{{ pct(quality.failureRate) }}</strong></span></div><p class="panel-note">命中率 =（有依据回答 + 证据不足）/ 成功问题；回答率 = 有依据回答 / 成功问题；失败率 = 失败 /（成功 + 失败）。这些指标不代表答案正确率。</p><div class="panel-heading"><h2>实际引用来源</h2></div><div class="source-ranking"><div v-for="(item, i) in quality.topSources" :key="item.docId"><span>{{ String(i + 1).padStart(2, '0') }}</span><strong>{{ item.docTitle }}</strong><small>{{ item.citationCount }} 次引用</small></div><p v-if="!quality.topSources.length" class="empty-state">暂无引用记录</p></div></template></section></template>
      <section v-if="tab === 'feedback'" class="panel"><div class="panel-heading"><h2>回答反馈</h2><span class="count-label">{{ feedbackTotal }} 条评价</span></div><form class="filter-bar" @submit.prevent="search"><select v-model="rating" aria-label="评价类型" @change="search"><option value="">全部评价</option><option value="LIKE">有帮助</option><option value="DISLIKE">没有帮助</option></select><label>起始时间<input v-model="from" type="datetime-local" aria-label="起始时间"></label><label>结束时间<input v-model="to" type="datetime-local" aria-label="结束时间"></label><button class="secondary">查询</button></form><div class="feedback-list"><button v-for="f in feedback" :key="f.feedbackId" class="feedback-item" @click="feedbackDetail = f"><div :class="['feedback-symbol', f.rating === 'LIKE' ? 'positive' : 'negative']"><Icon :name="f.rating === 'LIKE' ? 'like' : 'dislike'" /></div><div><strong>{{ f.question }}</strong><p>{{ f.remark || '未填写补充意见' }}</p><small>{{ date(f.updateTime) }} · {{ f.rating === 'LIKE' ? '有帮助' : '没有帮助' }}</small></div><Icon name="chevron" :size="17" /></button><div v-if="!feedback.length" class="empty-state"><Icon name="feedback" :size="32" /><h3>暂无符合条件的反馈</h3><p>学生提交的评价将在这里显示</p></div></div><div class="pagination"><span>仅展示与评价相关的问题、回答和引用</span><div><button class="secondary" :disabled="feedbackPage <= 1" @click="feedbackPage--; refresh()">上一页</button><span>{{ feedbackPage }}</span><button class="secondary" :disabled="feedbackPage * size >= feedbackTotal" @click="feedbackPage++; refresh()">下一页</button></div></div></section>
      </div>
    </main>
    <div v-if="uploadOpen" class="modal-backdrop" @click.self="!actionBusy && (uploadOpen = false)"><form class="modal upload-modal" role="dialog" aria-modal="true" aria-label="上传规章文档" @submit.prevent="upload"><div class="modal-header"><h2>上传规章文档</h2><button type="button" class="icon-button" aria-label="关闭上传" :disabled="actionBusy" @click="uploadOpen = false"><Icon name="close" /></button></div><p class="muted">文档上传后将自动解析、分块并建立检索索引。</p><label class="drop-zone"><Icon name="upload" :size="29" /><strong>{{ uploadFile?.name || '点击选择文档' }}</strong><span>PDF / DOCX / UTF-8 TXT · 最大 20 MiB</span><input ref="fileInput" type="file" accept=".pdf,.docx,.txt" aria-label="选择规章文件" @change="pickFile"></label><label for="doc-title">文档标题</label><input id="doc-title" v-model="uploadTitle" placeholder="输入清晰、准确的规章名称" required><label for="doc-category">规章分类</label><select id="doc-category" v-model="uploadCategory"><option v-for="(label, code) in categories" :key="code" :value="code">{{ label }}</option></select><div class="notice small">仅支持具有可提取文本的文档；不支持扫描件自动识别。请确认文件为当前适用的有效规章。</div><div v-if="error" class="error" role="alert">{{ error }}</div><div class="modal-footer"><button type="button" class="secondary" :disabled="actionBusy" @click="uploadOpen = false">取消</button><button class="primary" :disabled="actionBusy || !uploadFile">{{ actionBusy ? '正在上传…' : '上传并建立索引' }}</button></div></form></div>
    <div v-if="detail" class="modal-backdrop" @click.self="detail = null"><section class="modal document-modal" role="dialog" aria-modal="true" aria-label="文档详情"><div class="modal-header"><h2>{{ editing ? '编辑文档信息' : '文档与任务详情' }}</h2><button class="icon-button" aria-label="关闭详情" @click="detail = null"><Icon name="close" /></button></div><form v-if="editing" @submit.prevent="saveEdit"><label for="edit-title">展示标题</label><input id="edit-title" v-model="editTitle" required><label for="edit-category">分类</label><select id="edit-category" v-model="editCategory"><option v-for="(label, code) in categories" :key="code" :value="code">{{ label }}</option></select><p class="notice">修改展示信息不会替换正文，也不会重新生成向量。</p><div v-if="error" class="error">{{ error }}</div><div class="modal-footer"><button class="primary" :disabled="actionBusy">保存修改</button></div></form><template v-else><h3>{{ detail.title }}</h3><dl class="detail-grid"><dt>分类</dt><dd>{{ categories[detail.category] }}</dd><dt>原文件</dt><dd>{{ detail.originalFilename }} · {{ ((detail.fileSize || 0) / 1024).toFixed(1) }} KB</dd><dt>生命周期</dt><dd>{{ { ACTIVE: '启用中', DELETING: '正在删除', DELETED: '已删除' }[detail.lifecycleStatus] }}</dd><dt>可检索</dt><dd>{{ detail.searchable ? '是，已有已激活索引' : '否' }}</dd><dt>处理状态</dt><dd>{{ statuses[detail.vectorStatus] }}</dd><dt>当前有效代次</dt><dd>{{ detail.activeGeneration || '尚未激活' }}</dd><dt>当前任务</dt><dd>{{ detail.currentTask?.taskId }}</dd><dt>处理阶段</dt><dd>{{ detail.currentTask?.stage }}</dd><dt>开始时间</dt><dd>{{ date(detail.currentTask?.startedTime) }}</dd><dt>完成时间</dt><dd>{{ date(detail.currentTask?.finishedTime) }}</dd></dl><div v-if="detail.lastError" class="error">{{ detail.lastError.code }} · {{ detail.lastError.stage }}<br>{{ detail.lastError.message }}</div><div v-if="detail.cleanupError" class="error">{{ detail.cleanupError.code }} · {{ detail.cleanupError.message }}</div></template></section></div>
    <div v-if="feedbackDetail" class="modal-backdrop" @click.self="feedbackDetail = null"><section class="modal source-modal" role="dialog" aria-modal="true" aria-label="反馈详情"><div class="modal-header"><h2>反馈详情</h2><button class="icon-button" aria-label="关闭反馈详情" @click="feedbackDetail = null"><Icon name="close" /></button></div><span class="pill">{{ feedbackDetail.rating === 'LIKE' ? '有帮助' : '没有帮助' }}</span><h3>{{ feedbackDetail.question }}</h3><div class="full-text">{{ feedbackDetail.answer }}</div><p class="notice">学生意见：{{ feedbackDetail.remark || '未填写' }}</p><div v-for="s in feedbackDetail.sources" :key="s.sourceId" class="feedback-source"><h4>[{{ s.rankNo }}] {{ s.docTitle }}</h4><small v-if="s.sourceStatus !== 'ACTIVE'" class="warning-text">历史来源 · 已更新或删除</small><div class="full-text">{{ s.fullText }}</div></div></section></div>
  </div>
</template>

